import{_ as r,o as a,c as i,a2 as l}from"./chunks/framework.CqpfiAoK.js";const u=JSON.parse('{"title":"पूर्व-लंगर युग","description":"","frontmatter":{},"headers":[],"relativePath":"hi/71-前锚点时代.md","filePath":"hi/71-前锚点时代.md","lastUpdated":null}'),o={name:"hi/71-前锚点时代.md"};function d(e,t,n,s,h,g){return a(),i("div",null,[...t[0]||(t[0]=[l('<h1 id="पूर्व-लंगर-युग" tabindex="-1">पूर्व-लंगर युग <a class="header-anchor" href="#पूर्व-लंगर-युग" aria-label="Permalink to &quot;पूर्व-लंगर युग&quot;">​</a></h1><table tabindex="0"><thead><tr><th>मद</th><th>सामग्री</th></tr></thead><tbody><tr><td>दस्तावेज़ संख्या</td><td>71</td></tr><tr><td>मॉड्यूल</td><td>ऐतिहासिक युग और महत्वपूर्ण घटनाएँ</td></tr><tr><td>कीवर्ड</td><td>पूर्व-लंगर युग, शिकारी प्रणाली, सभ्यता-विच्छेद, अंधकार युग, नियम-अव्यवस्था</td></tr></tbody></table><h2 id="i-पूर्व-लंगर-युग-की-मूल-विशेषताएँ" tabindex="-1">I. पूर्व-लंगर युग की मूल विशेषताएँ <a class="header-anchor" href="#i-पूर्व-लंगर-युग-की-मूल-विशेषताएँ" aria-label="Permalink to &quot;I. पूर्व-लंगर युग की मूल विशेषताएँ&quot;">​</a></h2><p>पूर्व-लंगर युग हेंग-ब्रह्मांड के इतिहास का सबसे दीर्घ और सबसे अंधकारमय युग है। इस युग में ब्रह्मांड में कोई एकीकृत लंगर तंत्र नहीं था; मूल-नियम प्राकृतिक विसरण की अवस्था में थे, और ऊर्जा-संसाधनों का वितरण पूर्णतः «बलवान सब लेता है» वाले जंगल-नियम का पालन करता था। शिकारी साधना प्रणाली इस युग की परम प्रधान शक्ति थी; साधना-विधियाँ कुछ शक्तिशालियों और संप्रदायों द्वारा एकाधिकृत थीं, और निम्न जीवन-रूपों के पास लगभग कोई औपचारिक विकास-पथ नहीं था।</p><p>पूर्व-लंगर युग की केंद्रीय विशेषताओं को «पाँच अभाव» में संक्षेपित किया जा सकता है:</p><ul><li><strong>लंगर-रहित</strong>: कोई स्थिर नियम-लंगर नहीं, ऊर्जा-प्रवाह अव्यवस्थित, पटल-अवरोध दुर्बल।</li><li><strong>व्यवस्था-रहित</strong>: कोई एकीकृत सभ्यता-संस्थाएँ नहीं, पटलों के बीच निरंतर युद्ध, बार-बार नरसंहार।</li><li><strong>मार्ग-रहित</strong>: कोई अंतर-पटल संचार और यातायात-प्रौद्योगिकी नहीं; पटल मूलतः एक-दूसरे से पृथक।</li><li><strong>संरक्षण-रहित</strong>: शिक्षा, चिकित्सा, आवास जैसी कोई सार्वजनिक संरक्षण-प्रणाली नहीं; जीवन का अस्तित्व पूर्णतः व्यक्तिगत बल पर निर्भर।</li><li><strong>आशा-रहित</strong>: निम्न जीवन-रूपों के विकास-मार्ग पूर्णतः अवरुद्ध, वर्ग-स्थिरीकरण चरम पर।</li></ul><h2 id="ii-शिकारी-साधना-प्रणाली-का-संचालन-तंत्र" tabindex="-1">II. शिकारी साधना प्रणाली का संचालन-तंत्र <a class="header-anchor" href="#ii-शिकारी-साधना-प्रणाली-का-संचालन-तंत्र" aria-label="Permalink to &quot;II. शिकारी साधना प्रणाली का संचालन-तंत्र&quot;">​</a></h2><p>पूर्व-लंगर युग की साधना-प्रणाली केंद्रीय तंत्र के रूप में शिकार पर चलती थी। इसका मूल तर्क: ब्रह्मांड की मूल-ऊर्जा सीमित है, और किसी व्यक्ति का विकास अनिवार्यतः दूसरों की ऊर्जा की खपत की कीमत पर होता है। बलवान दुर्बलों की ऊर्जा, भाग्य और यहाँ तक कि मूल-तत्त्व को निगलकर अपना उत्थान करते हैं, जबकि दुर्बल बलवानों के «साधना-संसाधन» बन जाते हैं।</p><p>शिकारी प्रणाली के विशिष्ट रूप:</p><table tabindex="0"><thead><tr><th>शिकार-प्रकार</th><th>संचालन-विधि</th><th>ब्रह्मांड को हानि</th></tr></thead><tbody><tr><td>ऊर्जा-शिकार</td><td>अन्य जीवन-रूपों की साधना-ऊर्जा का प्रत्यक्ष निष्कर्षण</td><td>व्यक्ति की मृत्यु या साधना का पूर्ण नाश</td></tr><tr><td>भाग्य-शिकार</td><td>कला-विधियों या अनुष्ठानों से दूसरों का भाग्य और अवसर छीनना</td><td>कर्म-संतुलन नष्ट, पटल-स्तरीय विपत्तियाँ उत्पन्न</td></tr><tr><td>मूल-शिकार</td><td>अन्य जीवन-रूपों के मूल-नियम खंडों को निगलना</td><td>अपरिवर्तनीय विकास-क्षमता हानि</td></tr><tr><td>पटल-शिकार</td><td>बलवान सम्पूर्ण पटल को जीतकर पटल-जीवन को साधना-संसाधन बनाना</td><td>सभ्यता-विलोपन और पटल-उजाड़</td></tr><tr><td>नियम-शिकार</td><td>पटल के मूल-नियमों का नियंत्रण बलपूर्वक छीनना</td><td>नियम-नेटवर्क क्षतिग्रस्त, स्थान-पतन उत्पन्न</td></tr></tbody></table><p>अल्पावधि में शिकारी प्रणाली कुछ परम-शक्तिशाली उत्पन्न कर सकती है, किंतु दीर्घावधि में यह ब्रह्मांड की विकास-क्षमता का निरंतर उपभोग करती है, ब्रह्मांड की समग्र एंट्रॉपी-वृद्धि को त्वरित करती है और बार-बार सभ्यता-विच्छेद उत्पन्न करती है।</p><h2 id="iii-सभ्यता-विच्छेद-और-चक्रीय-विनाश" tabindex="-1">III. सभ्यता-विच्छेद और चक्रीय विनाश <a class="header-anchor" href="#iii-सभ्यता-विच्छेद-और-चक्रीय-विनाश" aria-label="Permalink to &quot;III. सभ्यता-विच्छेद और चक्रीय विनाश&quot;">​</a></h2><p>पूर्व-लंगर युग की सबसे प्रमुख ऐतिहासिक घटना «सभ्यता-विच्छेद» है। शिकारी प्रणाली के आंतरिक विरोधाभासों के कारण, प्रत्येक कभी-वैभवशाली सभ्यता अंततः अपने ही आत्म-विनाश की ओर बढ़ती थी:</p><ol><li><strong>उदय-काल</strong>: कोई जाति या संप्रदाय शिकार के माध्यम से तीव्र उत्थान कर, शक्तिशाली सभ्यता स्थापित करता है।</li><li><strong>चरम-काल</strong>: सभ्यता शक्ति-शिखर पर पहुँचती है, भीतर प्रतिरोध दबाती है, बाहर शिकार-विस्तार करती है।</li><li><strong>आंतरिक-संघर्ष काल</strong>: सभ्यता के भीतर के शक्तिशाली सीमित संसाधनों हेतु आंतरिक-संघर्ष करते हैं, शक्ति का क्षय होता है।</li><li><strong>पतन-काल</strong>: आंतरिक-संघर्ष से सभ्यता अत्यंत दुर्बल होती है, बाहरी शिकारी सुअवसर में आक्रमण करते हैं, सभ्यता विलुप्त होती है।</li><li><strong>विच्छेद-काल</strong>: सभ्यता के विलोपन के बाद उसका अधिकांश ज्ञान-प्रौद्योगिकी लुप्त हो जाती है, आगामी सभ्यताओं को शून्य से आरंभ करना पड़ता है।</li></ol><p>«उदय—चरम—आंतरिक-संघर्ष—पतन—विच्छेद» का यह चक्र पूर्व-लंगर युग में अनगिनत बार दोहराया गया। प्रत्येक चक्र ने ब्रह्मांड-मूल का विशाल उपभोग किया, जिससे ब्रह्मांड का समग्र विकास-स्तर दीर्घकाल तक स्थिर या प्रत्यावर्ती रहा।</p><h2 id="iv-पूर्व-लंगर-युग-के-अंत-के-पूर्व-संकेत" tabindex="-1">IV. पूर्व-लंगर युग के अंत के पूर्व-संकेत <a class="header-anchor" href="#iv-पूर्व-लंगर-युग-के-अंत-के-पूर्व-संकेत" aria-label="Permalink to &quot;IV. पूर्व-लंगर युग के अंत के पूर्व-संकेत&quot;">​</a></h2><p>पूर्व-लंगर युग के अंतिम दौर में ब्रह्मांड में परिवर्तन की घोषणा करने वाले अनेक पूर्व-संकेत प्रकट हुए:</p><ul><li><strong>नियम-क्षोभ की वृद्धि</strong>: दीर्घ शिकार से नियम-नेटवर्क गंभीर रूप से क्षतिग्रस्त, स्थान-पतन की घटनाएँ आवृत्त, पटल-अवरोध पतले।</li><li><strong>जीवन-क्षमता का ह्रास</strong>: शिकार योग्य मूल-ऊर्जा निरंतर दुर्लभ, शक्तिशालियों के बीच संसाधन-संघर्ष उग्र।</li><li><strong>शिकार-विरोधी विचार का अंकुरण</strong>: कुछ दूरदर्शी विचारक शिकारी प्रणाली के मूल दोषों पर चिंतन करने लगे, सहजीवन-विकास की प्रारंभिक अवधारणाएँ प्रस्तुत कीं।</li><li><strong>भिन्न-पटल संपर्क की वृद्धि</strong>: पटल-अवरोधों के पतले होने से भिन्न पटलों के बीच संपर्क बढ़ा, अंतर-पटल विचार-विनिमय संभव हुआ।</li><li><strong>प्रथम पीढ़ी लंगर-उम्मीदवारों का प्रकटन</strong>: ब्रह्मांड के कुछ कोनों में नियम-नेटवर्क से प्राकृतिक अनुनाद करने में सक्षम विशेष जीवन-रूप प्रकट हुए — भावी प्रथम पीढ़ी लंगर-जाग्रतकर्ताओं के पूर्ववर्ती।</li></ul><p>ये पूर्व-संकेत दर्शाते हैं कि शिकारी प्रणाली अपने अंतिम छोर पर पहुँच चुकी थी, और ब्रह्मांड एक पूर्णतः नई सभ्यता-आकृति का आह्वान कर रहा था।</p><h2 id="v-पूर्व-लंगर-युग-की-ऐतिहासिक-विरासत" tabindex="-1">V. पूर्व-लंगर युग की ऐतिहासिक विरासत <a class="header-anchor" href="#v-पूर्व-लंगर-युग-की-ऐतिहासिक-विरासत" aria-label="Permalink to &quot;V. पूर्व-लंगर युग की ऐतिहासिक विरासत&quot;">​</a></h2><p>पूर्व-लंगर युग अंधकारमय होते हुए भी निरर्थक नहीं था। इसने परवर्ती लंगर सहजीवी सभ्यता के लिए महत्वपूर्ण ऐतिहासिक विरासत छोड़ी:</p><ul><li><strong>शिक्षा-विरासत</strong>: शिकारी प्रणाली की बार-बार की विफलताओं ने सहजीवी सभ्यता को सबसे गहरा नकारात्मक उदाहरण दिया, यह सिद्ध करते हुए कि शिकार का मार्ग अवरुद्ध है।</li><li><strong>ज्ञान-विरासत</strong>: यद्यपि विशाल ज्ञान सभ्यता-विच्छेदों में लुप्त हुआ, फिर भी कुछ साधना-विधियाँ और नियम-बोध विविध माध्यमों से बचे रहे, तीन सौ मूल साधना-प्रणालियों के स्रोत-सामग्री बने।</li><li><strong>जीवन-विरासत</strong>: दीर्घ अंधकार-युग में उत्तरजीवी विविध जीवन-रूप भावी दस हजार जातियों के सहजीवन का जातीय आधार बने।</li><li><strong>इच्छा-विरासत</strong>: निम्न जीवन-रूपों की न्याय और आशा के प्रति स्थायी अभिलाषा लंगर-जागृति की सबसे मूल आध्यात्मिक प्रेरक-शक्ति है।</li></ul><h2 id="निष्कर्ष" tabindex="-1">निष्कर्ष <a class="header-anchor" href="#निष्कर्ष" aria-label="Permalink to &quot;निष्कर्ष&quot;">​</a></h2><p>पूर्व-लंगर युग हेंग-ब्रह्मांड के इतिहास की «अंधकार-पूर्व संध्या» है। इसकी दीर्घता और अंधकार, लंगर सहजीवी सभ्यता के जन्म की बहुमूल्यता और अनिवार्यता को ठीक उभारते हैं। पूर्व-लंगर युग को समझना, सहजीवी सभ्यता के «शिकार-विरोध, सहजीवन-समर्थन» मूल रुख के ऐतिहासिक मूल को समझना है — यह अमूर्त नैतिक उपदेश नहीं, बल्कि अनगिनत सभ्यताओं के विनाश से अर्जित रक्त-अश्रु शिक्षा है।</p><h2 id="संबंधित-दस्तावेज़" tabindex="-1">संबंधित दस्तावेज़ <a class="header-anchor" href="#संबंधित-दस्तावेज़" aria-label="Permalink to &quot;संबंधित दस्तावेज़&quot;">​</a></h2><ul><li>70-纪元划分总表 (युग-विभाजन मास्टर तालिका)</li><li>72-锚点觉醒纪元 (लंगर जागृति युग)</li><li>04-反掠夺主义核心论纲 (शिकार-विरोध का केंद्रीय सिद्धांत-लेख)</li></ul>',26)])])}const c=r(o,[["render",d]]);export{u as __pageData,c as default};
